#pragma once

// Cell-level model of the AOT30L/ART30RL wired-remote messages (see
// captures/matt-captures/settings-captures-notes.md and tools/fuji_packet.py, which this mirrors;
// tests/aot30_cells_test.cpp checks it against tests/golden_cells.txt generated by the Python model).
//
// A message is a list of "cells", each one bit time long. A cell holds a bus bit: the line level is the
// inverse (bus bit 1 = line low). The remote's bit time is 1980.8 us. No Arduino or ESP-IDF
// dependencies, so it can be unit-tested on a desktop compiler. Nothing here transmits.

#include <stddef.h>
#include <stdint.h>

namespace fuji_aot30 {

constexpr size_t kSettingCells = 84;
constexpr size_t kPollCells = 44;
constexpr size_t kOffCells = 33;
constexpr uint32_t kRemoteCellTenthsUs = 19808;  // 1980.8 us

enum class Mode : uint8_t { COOL = 1, HEAT = 2, FAN = 4, AUTO = 5 };
enum class Fan : uint8_t { HIGH = 1, MEDIUM = 2, LOW = 4, AUTO = 5 };

// Remote messages with every variable cell cleared; all other cells are constant in the captures.
constexpr char kSettingBase[] = "111111110101010001001011100000001000100000000001010000001011111101000000101111110100";
constexpr char kPollBase[] = "11111111010100010100101110010000010001000000";
constexpr char kOffBase[] = "111111110101001001001011100000000";

constexpr size_t kRoundCell = 27;
constexpr size_t kModeCell = 33;
constexpr size_t kFanCell = 37;
constexpr size_t kTempCell = 40;
constexpr size_t kEcoCell = 54;
constexpr size_t kPollRunningCell = 25;
constexpr size_t kPollPendingCell = 35;

constexpr uint8_t kFanModeTemp = 16;  // temperature field the remote sends in FAN mode

inline bool temp_in_range(Mode mode, uint8_t temp) {
  switch (mode) {
    case Mode::HEAT: return temp >= 16 && temp <= 30;
    case Mode::COOL:
    case Mode::AUTO: return temp >= 18 && temp <= 30;
    case Mode::FAN: return true;  // ignored, FAN carries no setpoint
  }
  return false;
}

inline void set_bits_(uint8_t *cells, size_t first, size_t width, uint8_t value) {
  for (size_t i = 0; i < width; i++) {
    cells[first + i] = (value >> i) & 1;
  }
}

inline void load_base_(uint8_t *cells, const char *base, size_t n) {
  for (size_t i = 0; i < n; i++) {
    cells[i] = base[i] == '1' ? 1 : 0;
  }
}

// Fills `cells` (kSettingCells entries) with the remote's setting message. `repeat` is the second round
// of a change (`22 13 ..`). Returns false and leaves `cells` untouched if a value is out of range.
inline bool build_setting(Mode mode, Fan fan, uint8_t temp, bool eco, bool repeat, uint8_t *cells) {
  switch (fan) {
    case Fan::HIGH:
    case Fan::MEDIUM:
    case Fan::LOW:
    case Fan::AUTO: break;
    default: return false;
  }
  if (mode == Mode::FAN) {
    temp = kFanModeTemp;
  } else if (!temp_in_range(mode, temp)) {
    return false;
  }
  load_base_(cells, kSettingBase, kSettingCells);
  set_bits_(cells, kRoundCell, 1, repeat ? 1 : 0);
  set_bits_(cells, kModeCell, 3, static_cast<uint8_t>(mode));
  set_bits_(cells, kFanCell, 3, static_cast<uint8_t>(fan));
  set_bits_(cells, kTempCell, 5, temp);
  set_bits_(cells, kEcoCell, 1, eco ? 1 : 0);
  return true;
}

inline void build_poll(bool running, bool pending, uint8_t *cells) {
  load_base_(cells, kPollBase, kPollCells);
  cells[kPollRunningCell] = running ? 1 : 0;
  cells[kPollPendingCell] = pending ? 1 : 0;
}

inline void build_off(uint8_t *cells) { load_base_(cells, kOffBase, kOffCells); }

}  // namespace fuji_aot30
